    if obj:
        parsed_date = dateparser.parse(
            obj, languages=['en'], Settings={'TIMEZONE': 'UTC'})
        if parsed_date is None:
            remaining_options = {
                'LANGUAGE': 'en',
                'PREFER_DATES_FROM': 'history',
                'DATE_ORDER': 'DMY'
            }
            parsed_date = dateparser.parse(
