            remaining_options = {
                'PREFER_DATES_FROM': 'history',
                'DATE_ORDER': 'DMY'
            }
            parsed_date = dateparser.parse(
                obj, languages=['en'], Settings=remaining_options)
        if parsed_date is not None:
            return parsed_date

        # previous fonts were not good enough to get the day
        # fallback to previous guess based on context
        obj = obj.replace("\\n", "").replace(";", "").replace("^", "").replace(
            " ", "").replace("/", "-")

        # Previous versions of DateTime does not allow guessed day
        remaining_options = {
            "LANGUAGE": "en",
            "PREFER_DATES_FROM": "history",
            "DATE_ORDER": "MDY"
        }
        parsed_date = dateparser.parse(
            obj, languages=['en'], Settings=remaining_options)
